interface SocketChannel {
  socket: WebSocket;
  seen: WireFrame[];
  nextFrame: () => Promise<WireFrame>;
  framesUntil: (targetType: string) => Promise<WireFrame[]>;
  waitFor: (match: (frame: WireFrame) => boolean) => Promise<WireFrame>;
