    const targetId = typeof rows1[0]?.sessionId === 'string' ? rows1[0].sessionId : '';
    const resumedChannel = await openChannel(`${baseUrl}?sessionId=${targetId}`);
    const connected2 = await resumedChannel.nextFrame();
    resumedChannel.socket.send(JSON.stringify({type: 'ping', timestamp: 2}));
    const replay = await resumedChannel.framesUntil('pong');

    expect({
