        created: ISO_STAMP.test(String(row.createdAt)),
        updated: ISO_STAMP.test(String(row.updatedAt)),
        entries: row.entries,
        authHeaders: row.authHeaders,
      })),
      recordedCalls,
      resumed: {
        sessionId: connected2.sessionId,
        resumed: connected2.resumed,
        entryCount: connected2.entryCount,
        contents: replay.filter(frame => frame.type === 'entry_upsert').map(frame => frame.entry?.content),
      },
    }).toEqual({
      connectedKeys: ['examplePrompts', 'message', 'resumed', 'sessionId', 'type'],
      page1Type: 'conversation_list',
      fenceTypes: ['pong'],
      page1Ids: ['s-newest', 's-middle'],
      page2Ids: ['s-oldest', connected1.sessionId],
      rowShapes: [
        {created: true, updated: true, entries: undefined, authHeaders: undefined},
        {created: true, updated: true, entries: undefined, authHeaders: undefined},
        {created: true, updated: true, entries: undefined, authHeaders: undefined},
        {created: true, updated: true, entries: undefined, authHeaders: undefined},
      ],
      recordedCalls: [
        {userId: 'u1', options: {limit: 2, before: undefined}},
        {userId: 'u1', options: {limit: 2, before: {updatedAt: '2030-01-01T09:00:00.000Z', sessionId: 's-middle'}}},
      ],
      resumed: {
        sessionId: 's-newest',
        resumed: true,
        entryCount: 2,
        contents: ['newest', 'reply'],
      },
    });
  });

  it('answers UNSUPPORTED when history is omitted, when the store omits listFor, or when MongoSessionStore cannot find', async () => {
    const omitted = await probeUnsupported({store: new InMemorySessionStore()});
    const withoutListFor = await probeUnsupported({store: fiveMemberStore, history: {enabled: true}});
    const withoutFind = await probeUnsupported({
      store: new MongoSessionStore({collection: collectionWithoutFind()}),
      history: {enabled: true},
    });

    const expected = {type: 'error', code: 'UNSUPPORTED', hasMessage: true, afterTypes: ['pong']};
    expect({omitted, withoutListFor, withoutFind}).toEqual({
      omitted: expected,
      withoutListFor: expected,
      withoutFind: expected,
    });
  });

  it('answers SERVER_ERROR with no store detail when listFor rejects, keeps the socket open, and logs the sessionId without user content', async () => {
    const captured = installLogCapture();
    const inner = new InMemorySessionStore();
    const prior = inner.create('prior', 'u1');
    prior.entries.push({role: 'user', content: 'private user prompt', timestamp: '2030-01-01T08:00:00.000Z'});
    const store = failingListStore(inner, new Error('ECONNREFUSED db.internal:27017'));

    const {baseUrl} = await startListEngine({store, history: {enabled: true}});
    const channel = await openChannel(baseUrl);
    const connected = await channel.nextFrame();
    channel.socket.send(JSON.stringify({type: 'list_conversations'}));
    const reply = await channel.nextFrame();
    channel.socket.send(JSON.stringify({type: 'ping', timestamp: 9}));
    const afterReply = await channel.nextFrame();

    const errorLines = captured.filter(line => line.level === 'error');
    const leaked = ['ECONNREFUSED', 'db.internal', '27017'].filter(term => String(reply.message).includes(term));

    expect({
      type: reply.type,
      code: reply.code,
      leakedToClient: leaked,
      keptOpen: afterReply.type === 'pong' && afterReply.timestamp === 9,
      loggedSession: errorLines.some(line => line.fields?.sessionId === connected.sessionId),
      leakedUserContent: captured.some(line => JSON.stringify(line).includes('private user prompt')),
    }).toEqual({
      type: 'error',
      code: 'SERVER_ERROR',
      leakedToClient: [],
      keptOpen: true,
      loggedSession: true,
      leakedUserContent: false,
    });
  });

  it('answers list_conversations off the per-session lock while a user_message stream is still open', async () => {
    const inTurn = deferred();
    const releaseTurn = deferred();
    const {baseUrl} = await startListEngine({
      store: new InMemorySessionStore(),
      history: {enabled: true},
      beforeModelResponse: async (_session, prompt) => {
        inTurn.release();
        await releaseTurn.until;
        return prompt;
      },
    });

    const channel = await openChannel(baseUrl);
    await channel.nextFrame();

    channel.socket.send(JSON.stringify({type: 'user_message', content: 'hold open'}));
    await inTurn.until;

    const listPromise = channel.waitFor(frame => frame.type === 'conversation_list' || frame.type === 'error');
    channel.socket.send(JSON.stringify({type: 'list_conversations'}));
    const response = await listPromise;
    const seenStreamEndBeforeList = channel.seen.some(frame => frame.type === 'stream_end');

    const streamEndPromise = channel.waitFor(frame => frame.type === 'stream_end');
    releaseTurn.release();
    await streamEndPromise;

    expect({
      responseType: response.type,
