    });
  });

  it('validates list_conversations frames, stripping extra fields and refusing bad limit or before values by field name', () => {
    const plain = validateMessage({type: 'list_conversations'});
    const paged = validateMessage({
      type: 'list_conversations',
      limit: 20,
      before: {updatedAt: '2026-09-30T08:00:00.000Z', sessionId: 's1'},
